ngth ti\n        frogs[i] = {xi, xi + ti, i, 0};\n    }\n    // sort frogs by x\n    sort(frogs.begin(), frogs.end(), [](const Frog& a, const Frog& b){\n        if(a.x != b.x) return a.x < b.x;\n        return a.idx < b.idx;\n    });\n    vector<long long> xs(n);\n    for(int i=0;i<n;++i) xs[i] = frogs[i].x;\n    SegTree st(n);\n    if(n > 0){\n        vector<long long> init(n);\n        for(int i=0;i<n;++i) init[i] = frogs[i].reach;\n        st.build(init);\n    }\n    multimap<long long,long long> waiting; // position -> size (multimap to support duplicates)\n\n    for(int j=0;j<m;++j){\n        long long p, b;\n        cin >> p >> b;\n        int idx = int(upper_bound(xs.begin(), xs.end(), p) - xs.begin()) - 1; // last frog with x <= p\n        if(n>0 && idx >= 0){\n            int frogIndex = st.findFirst(idx, p); // leftmost frog in [0..idx] with reach >= p\n            if(frogIndex != -1){\n                // frog eats this mosquito\n                frogs[frogIndex].cnt += 1;\n                frogs[frogIndex].reach += b;\n                st.update(frogIndex, frogs[frogIndex].reach);\n                // Now try to eat waiting mosquitoes that are now reachable by this frog\n                while(true){\n                    auto it = waiting.lower_bound(frogs[frogIndex].x);\n                    if(it != waiting.end() && it->first <= frogs[frogIndex].reach){\n                        long long add = it->second;\n                        waiting.erase(it);\n                        frogs[frogIndex].cnt += 1;\n                        frogs[frogIndex].reach += add;\n                        st.update(frogIndex, frogs[frogIndex].reach);\n                    } else break;\n                }\n            } else {\n                // no frog can eat on arrival\n                waiting.insert({p, b});\n            }\n        } else {\n            // no frog to the left of p, mosquito just waits\n            waiting.insert({p, b});\n        }\n    }\n\n    // Prepare output in